        return PhosphorIconsBold.yinYang;
      case PhosphorIconsStyle.fill:
        return PhosphorIconsFill.yinYang;
      case PhosphorIconsStyle.duotone:
        return PhosphorIconsDuotone.yinYang;
    }
  }

  /// regular: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/regular/youtubeLogo.svg)
  /// thin: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/thin/youtubeLogo-thin.svg)
  /// light: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/light/youtubeLogo-light.svg)
  /// bold: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/bold/youtubeLogo-bold.svg)
  /// fill: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/fill/youtubeLogo-fill.svg)
  /// duotone: ![youtubeLogo](https://raw.githubusercontent.com/phosphor-icons/core/main/assets/duotone/youtubeLogo-duotone.svg)
  static IconData youtubeLogo([PhosphorIconsStyle style = PhosphorIconsStyle.regular]) {
    switch (style) {
      case PhosphorIconsStyle.regular:
        return PhosphorIconsRegular.youtubeLogo;
      case PhosphorIconsStyle.thin:
        return PhosphorIconsThin.youtubeLogo;
      case PhosphorIconsStyle.light:
        return PhosphorIconsLight.youtubeLogo;
      case PhosphorIconsStyle.bold:
        return PhosphorIconsBold.youtubeLogo;
      case PhosphorIconsStyle.fill:
        return PhosphorIconsFill.youtubeLogo;
      case PhosphorIconsStyle.duotone:
        return PhosphorIconsDuotone.youtubeLogo;
    }
  }
}